# Verrou d'instance unique : empêche de lancer plusieurs fois l'application en même temps.
# Le handle / fichier reste volontairement ouvert pendant toute la durée du process.
ERROR_ALREADY_EXISTS = 183
_SINGLE_INSTANCE_MUTEX_HANDLE: Any = None
_SINGLE_INSTANCE_LOCK_FILE: Any = None
SINGLE_INSTANCE_MUTEX_NAME = "Local\\RLOverlayStudio_SingleInstance_v1"
SHOW_WINDOW_EVENT_NAME = "Local\\RLOverlayStudio_ShowWindow_v1"
_SHOW_WINDOW_EVENT_HANDLE: Any = None
WAIT_OBJECT_0 = 0

def notify_existing_instance_show_window() -> bool:
    """Demande à l'instance déjà active d'afficher sa fenêtre principale."""
    if os.name == "nt":
        try:
            kernel32 = ctypes.windll.kernel32
            kernel32.CreateEventW.argtypes = (ctypes.c_void_p, ctypes.wintypes.BOOL, ctypes.wintypes.BOOL, ctypes.wintypes.LPCWSTR)
            kernel32.CreateEventW.restype = ctypes.wintypes.HANDLE
            kernel32.SetEvent.argtypes = (ctypes.wintypes.HANDLE,)
            kernel32.SetEvent.restype = ctypes.wintypes.BOOL
            kernel32.CloseHandle.argtypes = (ctypes.wintypes.HANDLE,)
            kernel32.CloseHandle.restype = ctypes.wintypes.BOOL
            handle = kernel32.CreateEventW(None, False, False, SHOW_WINDOW_EVENT_NAME)
            if not handle:
                return False
            try:
                return bool(kernel32.SetEvent(handle))
            finally:
                try:
                    kernel32.CloseHandle(handle)
                except Exception:
                    pass
        except Exception:
            return False

    try:
        signal_path = Path(tempfile.gettempdir()) / "rl_overlay_studio_show_window.signal"
        signal_path.write_text(str(time.time()), encoding="utf-8")
        return True
    except Exception:
        return False

def acquire_single_instance_lock() -> bool:
    """Retourne False si RL Overlay Studio est déjà lancé dans la session Windows."""
    global _SINGLE_INSTANCE_MUTEX_HANDLE, _SINGLE_INSTANCE_LOCK_FILE

    if os.name == "nt":
        try:
            kernel32 = ctypes.windll.kernel32
            kernel32.CreateMutexW.argtypes = (ctypes.c_void_p, ctypes.wintypes.BOOL, ctypes.wintypes.LPCWSTR)
            kernel32.CreateMutexW.restype = ctypes.wintypes.HANDLE
            kernel32.GetLastError.argtypes = ()
            kernel32.GetLastError.restype = ctypes.wintypes.DWORD
            kernel32.CloseHandle.argtypes = (ctypes.wintypes.HANDLE,)
            kernel32.CloseHandle.restype = ctypes.wintypes.BOOL

            handle = kernel32.CreateMutexW(None, False, SINGLE_INSTANCE_MUTEX_NAME)
            last_error = int(kernel32.GetLastError())
            if not handle:
                # Si Windows refuse la création du mutex, on ne bloque pas l'application.
                return True
            if last_error == ERROR_ALREADY_EXISTS:
                try:
                    kernel32.CloseHandle(handle)
                except Exception:
                    pass
                return False
            _SINGLE_INSTANCE_MUTEX_HANDLE = handle
            return True
        except Exception:
            # Sécurité : si le verrou système échoue pour une raison inattendue,
            # on évite d'empêcher totalement l'ouverture de l'application.
            return True

    # Fallback utile si l'app est lancée depuis les sources hors Windows.
    try:
        import fcntl
        lock_path = Path(tempfile.gettempdir()) / "rl_overlay_studio_single_instance.lock"
        lock_file = lock_path.open("w", encoding="utf-8")
        fcntl.flock(lock_file.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
        lock_file.seek(0)
        lock_file.truncate()
        lock_file.write(str(os.getpid()))
        lock_file.flush()
        _SINGLE_INSTANCE_LOCK_FILE = lock_file
        return True
    except Exception:
        return False

def show_already_running_message() -> None:
    message = (
        "RL Overlay Studio est déjà ouvert.\n\n"
        "La fenêtre de l'application déjà lancée va être affichée."
    )
    if os.name == "nt":
        try:
            ctypes.windll.user32.MessageBoxW(None, message, APP_NAME, 0x00000040)
            return
        except Exception:
            pass
    try:
        print(message, file=sys.stderr)
    except Exception:
        pass

