def _full_error_log_text(value: Any) -> str:
    try:
        if isinstance(value, (dict, list, tuple)):
            return json.dumps(value, ensure_ascii=False, indent=2, default=str)
        return str(value)
    except Exception:
        try:
            return repr(value)
        except Exception:
            return "<unprintable>"

def _looks_like_error_log(message: Any) -> bool:
    msg = _full_error_log_text(message).casefold()
    if not msg:
        return False
    return any(token in msg for token in ERROR_LOG_KEYWORDS)

def append_recent_error_log(source: str, message: Any, extra: Optional[Any] = None) -> None:
    """Écrit une erreur complète dans AppData/Logs/errors_recent.log sans tronquer le message."""
    try:
        ERROR_LOG_DIR.mkdir(parents=True, exist_ok=True)
        stamp = time.strftime("%Y-%m-%d %H:%M:%S")
        header = f"\n[{stamp}] {source or 'ERROR'} · {APP_VERSION_LABEL}\n"
        sep = "-" * 92 + "\n"
        body = _full_error_log_text(message)
        extra_text = ""
        if extra is not None:
            extra_text = "\n\n[extra]\n" + _full_error_log_text(extra)
        entry = header + sep + body + extra_text + "\n"
        with ERROR_LOG_PATH.open("a", encoding="utf-8") as f:
            f.write(entry)

        try:
            if ERROR_LOG_PATH.stat().st_size > int(ERROR_LOG_MAX_BYTES):
                raw = ERROR_LOG_PATH.read_text(encoding="utf-8", errors="replace")
                keep = raw[-int(ERROR_LOG_MAX_BYTES * 0.72):]
                ERROR_LOG_PATH.write_text(
                    f"[{stamp}] Rotation automatique · conservation des erreurs récentes\n" + keep,
                    encoding="utf-8",
                )
        except Exception:
            pass
    except Exception:
        pass

