def _design_font_available() -> bool:
    try:
        wanted = DESIGN_FONT_FAMILY.casefold()
        return any(str(name).casefold() == wanted for name in QFontDatabase.families())
    except Exception:
        return False


def _register_design_font_file(path: Path, loaded: List[str]) -> None:
    try:
        if not path.is_file():
            return
        font_id = QFontDatabase.addApplicationFont(str(path))
        if font_id < 0:
            return
        loaded.extend(QFontDatabase.applicationFontFamilies(font_id))
    except Exception:
        pass


def load_local_design_fonts() -> List[str]:
    """Garantit autant que possible que Montserrat est réellement disponible dans Qt.

    Le problème historique du dock venait du fait que les QSS demandaient "Montserrat"
    sans qu'aucune police Montserrat ne soit forcément installée sur Windows. Qt basculait
    alors silencieusement sur Segoe UI. La release reste volontairement ``no-fonts`` :
    aucun fichier de police n'est distribué dans le ZIP. Au premier lancement, si Montserrat
    n'est pas déjà installée, l'app télécharge les fichiers officiels Google Fonts dans le
    cache utilisateur, puis les enregistre avec QFontDatabase. Les lancements suivants
    utilisent uniquement le cache local.
    """
    loaded: List[str] = []

    # 1) Polices locales de développement éventuelles.
    try:
        if LOCAL_FONT_DIR.exists():
            for font_file in sorted(LOCAL_FONT_DIR.rglob("*")):
                if font_file.suffix.lower() in {".ttf", ".otf", ".ttc"}:
                    _register_design_font_file(font_file, loaded)
    except Exception:
        pass

    # 2) Cache utilisateur persistant.
    try:
        DESIGN_FONT_CACHE_DIR.mkdir(parents=True, exist_ok=True)
        for font_file in sorted(DESIGN_FONT_CACHE_DIR.glob("Montserrat*")):
            if font_file.suffix.lower() in {".ttf", ".otf", ".ttc"}:
                _register_design_font_file(font_file, loaded)
    except Exception:
        pass

    if _design_font_available():
        return loaded

    # 3) Téléchargement officiel à la demande. Temps d'attente volontairement court :
    # l'absence d'Internet ne doit jamais bloquer le lancement de l'application.
    for filename, url in DESIGN_FONT_DOWNLOADS.items():
        target = DESIGN_FONT_CACHE_DIR / filename
        try:
            if not target.is_file() or target.stat().st_size < 50_000:
                request = urllib.request.Request(
                    url,
                    headers={"User-Agent": "RL-Overlay-Studio/8.19 Montserrat-loader"},
                )
                with urllib.request.urlopen(request, timeout=2.0) as response:
                    payload = response.read(2_000_000)
                if len(payload) >= 50_000:
                    tmp = target.with_suffix(target.suffix + ".tmp")
                    tmp.write_bytes(payload)
                    tmp.replace(target)
            _register_design_font_file(target, loaded)
        except Exception:
            continue

    return loaded


def verify_design_assets_lock() -> List[str]:
    """Vérifie que les assets visuels principaux n'ont pas disparu ou changé."""
    warnings: List[str] = []
    try:
        if not ASSETS_LOCK_PATH.is_file():
            return ["Manifest assets introuvable : assets/ASSETS_LOCK_BETA_6.7.json"]
        manifest = json.loads(ASSETS_LOCK_PATH.read_text(encoding="utf-8"))
        for item in manifest.get("files", []):
            rel = str(item.get("path") or "").replace("\\", "/")
            expected = str(item.get("sha256") or "")
            if not rel or not expected:
                continue
            path = RESOURCE_DIR / rel
            if not path.is_file():
                warnings.append(f"Asset manquant : {rel}")
                continue
            digest = hashlib.sha256(path.read_bytes()).hexdigest()
            if digest.lower() != expected.lower():
                warnings.append(f"Asset modifié : {rel}")
    except Exception as exc:
        warnings.append(f"Impossible de vérifier les assets : {exc}")
    return warnings


def verify_app_protection_lock() -> List[str]:
    """Contrôle d'intégrité anti-copie / anti-modification des fichiers importants.

    Beta 7.61 : ce n'est pas un DRM inviolable. Le but est de rendre les copies
    modifiées et les remplacements d'assets beaucoup plus visibles/difficiles :
    l'app vérifie un manifeste de hashes SHA256 généré au packaging.
    """
    warnings: List[str] = []
    try:
        if not APP_PROTECTION_MANIFEST_PATH.is_file():
            return ["Manifest protection introuvable : assets/APP_PROTECTION_MANIFEST_BETA_7.17.json"]

        manifest = json.loads(APP_PROTECTION_MANIFEST_PATH.read_text(encoding="utf-8"))
        files = manifest.get("files", [])
        if not isinstance(files, list):
            return ["Manifest protection invalide : liste files absente"]

        frozen = bool(getattr(sys, "frozen", False))
        checked = 0
        for item in files:
            if not isinstance(item, dict):
                continue
            rel = str(item.get("path") or "").replace("\\", "/").strip()
            expected = str(item.get("sha256") or "").strip().lower()
            if not rel or not expected:
                continue
            if frozen and bool(item.get("skip_when_frozen", False)):
                continue

            path = RESOURCE_DIR / rel
            if not path.is_file():
                if not bool(item.get("optional", False)):
                    warnings.append(f"Fichier protection manquant : {rel}")
                continue

            digest = hashlib.sha256(path.read_bytes()).hexdigest().lower()
            checked += 1
            if digest != expected:
                warnings.append(f"Fichier protection modifié : {rel}")

        if checked <= 0:
            warnings.append("Manifest protection non vérifié : aucun fichier contrôlé")
    except Exception as exc:
        warnings.append(f"Impossible de vérifier la protection : {exc}")
    return warnings

