def _install_rank_floor_tables(floors_by_playlist: Dict[str, Tuple[int, ...]]) -> None:
    """Construit des tables rank déterministes depuis les seuils Division I."""
    meta = {short: (label, asset) for _low, _high, short, label, asset in RANK_TABLES["3v3"]}
    for playlist, floors in floors_by_playlist.items():
        rows: List[Tuple[int, Optional[int], str, str, str]] = []
        for idx, (short, low) in enumerate(zip(_EXTRA_RANK_ORDER, floors)):
            high: Optional[int] = None if idx == len(floors) - 1 else int(floors[idx + 1]) - 1
            label, asset = meta[short]
            rows.append((int(low), high, short, label, asset))
        RANK_TABLES[playlist] = rows


