def _normalized_division_floors(playlist: str, short: str, low: int, high: Optional[int]) -> Optional[Tuple[int, int, int, int]]:
    """Rend déterministes les plages publiques qui se chevauchent aux promotions/démotions."""
    mode_floors = MAIN_MODE_DIVISION_FLOORS.get(playlist) or EXTRA_MODE_DIVISION_FLOORS.get(playlist)
    raw = mode_floors.get(short) if mode_floors is not None else None
    if not raw:
        return None
    if high is None or str(short).upper() == "SSL":
        return (int(low), int(low), int(low), int(low))

    lo = int(low)
    hi = max(lo + 3, int(high))
    raw_values = [lo, int(raw[1]), int(raw[2]), int(raw[3])]
    out = [lo]
    for i in range(1, 4):
        remaining_after = 3 - i
        max_allowed = hi - remaining_after
        candidate = raw_values[i]
        if candidate <= out[-1] or candidate > max_allowed:
            # Cherche le prochain seuil public encore exploitable et répartit
            # l'intervalle jusqu'à cet ancrage. Cela évite qu'un chevauchement
            # fasse disparaître entièrement une Division I/II/III/IV.
            anchor = None
            anchor_index = None
            for j in range(i + 1, 4):
                rv = raw_values[j]
                if out[-1] < rv <= hi - (3 - j):
                    anchor = rv
                    anchor_index = j
                    break
            if anchor is not None and anchor_index is not None:
                steps = max(1, anchor_index - (i - 1))
                candidate = out[-1] + max(1, int((anchor - out[-1]) / steps))
            else:
                slots = max(1, 4 - i)
                candidate = out[-1] + max(1, int((hi - out[-1]) / slots))
        candidate = max(out[-1] + 1, min(max_allowed, int(candidate)))
        out.append(candidate)
    return (out[0], out[1], out[2], out[3])


