def extract_playlist_id_from_payload(*payloads: Any) -> Optional[int]:
    numeric_tails = {"playlistid", "playlist_id", "playlistnum", "playlist_num"}
    playlist_tails = {"playlist"}
    for payload in payloads:
        for path, value in iter_json_values(payload):
            if isinstance(value, bool):
                continue
            tail = path.lower().replace("-", "_").split(".")[-1]
            tail = re.sub(r"\[[0-9]+\]", "", tail)
            if tail in numeric_tails:
                if isinstance(value, (int, float)):
                    return int(value)
                if isinstance(value, str):
                    m = re.fullmatch(r"\s*(\d{1,3})\s*", value)
                    if m:
                        return int(m.group(1))
            elif tail in playlist_tails:
                # Ne jamais extraire le "3" de "Ranked Standard 3v3" : seuls les vrais champs numériques comptent.
                if isinstance(value, (int, float)):
                    return int(value)
                if isinstance(value, str) and value.strip().isdigit():
                    return int(value.strip())
    return None


_LAUNCH_LOG_DISCOVERY_CACHE: Dict[str, Any] = {"ts": 0.0, "paths": []}
_LAUNCH_LOG_DISCOVERY_TTL_SECONDS = 300.0


def _path_key_safe(path: Path) -> str:
    try:
        return str(path.resolve()).lower()
    except Exception:
        return str(path).lower()


def _add_unique_path(paths: List[Path], seen: Set[str], path: Path) -> None:
    try:
        p = Path(path)
        key = _path_key_safe(p)
    except Exception:
        return
    if key in seen:
        return
    seen.add(key)
    paths.append(p)


def _add_launch_candidates_from_logs_dir(base: Path, candidates: List[Path], seen: Set[str]) -> None:
    """Ajoute les fichiers Launch probables depuis un dossier TAGame\\Logs."""
    try:
        base = Path(base)
    except Exception:
        return

    # Chemins directs : Rocket League utilise généralement Launch.log, mais certaines
    # installations ou copies exposent Launch.txt ou un fichier sans extension.
    for name in ("Launch.log", "Launch.txt", "Launch"):
        _add_unique_path(candidates, seen, base / name)

    try:
        if not base.exists():
            return
        launch_folder = base / "Launch"
        if launch_folder.exists() and launch_folder.is_dir():
            for p in sorted(launch_folder.glob("Launch*"), key=lambda x: x.stat().st_mtime if x.exists() else 0, reverse=True):
                name_l = p.name.lower()
                if "backup" in name_l or name_l.endswith(".bak"):
                    continue
                if p.is_file():
                    _add_unique_path(candidates, seen, p)
        for p in sorted(base.glob("Launch*"), key=lambda x: x.stat().st_mtime if x.exists() else 0, reverse=True):
            name_l = p.name.lower()
            if "backup" in name_l or name_l.endswith(".bak"):
                continue
            if p.is_file():
                _add_unique_path(candidates, seen, p)
            elif p.is_dir():
                for child in sorted(p.glob("Launch*"), key=lambda x: x.stat().st_mtime if x.exists() else 0, reverse=True):
                    child_l = child.name.lower()
                    if "backup" in child_l or child_l.endswith(".bak"):
                        continue
                    if child.is_file():
                        _add_unique_path(candidates, seen, child)
    except Exception:
        pass


def _candidate_windows_document_roots() -> List[Path]:
    """Retourne les dossiers Documents probables, y compris Documents redirigé OneDrive."""
    roots: List[Path] = []
    seen: Set[str] = set()
    env = os.environ

    def add(path: Any) -> None:
        try:
            raw = str(path or "").strip()
            if not raw:
                return
            _add_unique_path(roots, seen, Path(os.path.expandvars(os.path.expanduser(raw))))
        except Exception:
            pass

    # Dossier Documents standard + profils OneDrive connus.
    userprofile = str(env.get("USERPROFILE", "") or "").strip()
    if userprofile:
        add(Path(userprofile) / "Documents")
        add(Path(userprofile) / "OneDrive" / "Documents")
        try:
            for one in Path(userprofile).glob("OneDrive*"):
                add(one / "Documents")
        except Exception:
            pass
    for key in ("OneDrive", "OneDriveConsumer", "OneDriveCommercial"):
        value = str(env.get(key, "") or "").strip()
        if value:
            add(Path(value) / "Documents")
    homepath = str(env.get("HOMEPATH", "") or "").strip()
    homedrive = str(env.get("HOMEDRIVE", "") or "").strip()
    if homepath:
        hp = Path(homepath)
        if homedrive and not str(hp).startswith("\\"):
            hp = Path(homedrive + homepath)
        add(hp / "Documents")
        add(hp / "OneDrive" / "Documents")
    try:
        add(Path.home() / "Documents")
        add(Path.home() / "OneDrive" / "Documents")
    except Exception:
        pass

    # Documents Windows peut être redirigé hors OneDrive ou vers un autre chemin.
    if os.name == "nt":
        try:
            import winreg  # type: ignore
            keys = [
                (winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Explorer\User Shell Folders"),
                (winreg.HKEY_CURRENT_USER, r"Software\Microsoft\Windows\CurrentVersion\Explorer\Shell Folders"),
            ]
            value_names = ("Personal", "{F42EE2D3-909F-4907-8871-4C22FC0BF756}")
            for root_key, subkey in keys:
                try:
                    with winreg.OpenKey(root_key, subkey) as k:
                        for value_name in value_names:
                            try:
                                value, _ = winreg.QueryValueEx(k, value_name)
                                add(value)
                            except Exception:
                                pass
                except Exception:
                    pass
        except Exception:
            pass
    return roots


def _existing_windows_drive_roots() -> List[Path]:
    """Liste courte des lecteurs Windows existants pour une recherche ciblée."""
    drives: List[Path] = []
    seen: Set[str] = set()
    if os.name != "nt":
        return drives
    try:
        system_drive = str(os.environ.get("SystemDrive", "C:") or "C:").rstrip("\\/")
        if system_drive:
            _add_unique_path(drives, seen, Path(system_drive + "\\"))
    except Exception:
        pass
    for letter in "CDEFGHIJKLMNOPQRSTUVWXYZ":
        try:
            root = Path(f"{letter}:\\")
            if root.exists():
                _add_unique_path(drives, seen, root)
        except Exception:
            continue
    return drives


def _discover_launch_log_paths_targeted_scan() -> List[Path]:
    """Découvre My Games\\Rocket League\\TAGame\\Logs\\Launch sur le PC avec un cache.

    Objectif : ne plus dépendre uniquement de OneDrive. On garde les chemins
    standards rapides, puis on ajoute une recherche ciblée sur les profils Windows
    et les lecteurs existants sans faire de scan récursif massif du disque.
    """
    now = time.monotonic()
    try:
        cached_paths = list(_LAUNCH_LOG_DISCOVERY_CACHE.get("paths") or [])
        cached_ts = float(_LAUNCH_LOG_DISCOVERY_CACHE.get("ts") or 0.0)
        if cached_paths and (now - cached_ts) < _LAUNCH_LOG_DISCOVERY_TTL_SECONDS:
            return [Path(p) for p in cached_paths]
    except Exception:
        pass

    candidates: List[Path] = []
    seen: Set[str] = set()

    def add_logs_dir(logs_dir: Path) -> None:
        _add_launch_candidates_from_logs_dir(logs_dir, candidates, seen)

    for docs in _candidate_windows_document_roots():
        add_logs_dir(docs / "My Games" / "Rocket League" / "TAGame" / "Logs")

    # Recherche ciblée sur tous les profils Windows, utile quand OneDrive n'est pas
    # utilisé ou quand Documents est dans C:\Users\<User>\Documents.
    for drive in _existing_windows_drive_roots():
        for pattern in (
            "Users/*/Documents/My Games/Rocket League/TAGame/Logs",
            "Users/*/OneDrive*/Documents/My Games/Rocket League/TAGame/Logs",
            "Users/*/*/Documents/My Games/Rocket League/TAGame/Logs",
            "Documents/My Games/Rocket League/TAGame/Logs",
            "My Games/Rocket League/TAGame/Logs",
        ):
            try:
                for logs_dir in drive.glob(pattern):
                    add_logs_dir(logs_dir)
            except Exception:
                pass

    # Dernier filet de sécurité limité au profil utilisateur courant : on cherche
    # des dossiers "My Games" sans parcourir tout le PC et on s'arrête rapidement.
    try:
        profile = Path(os.environ.get("USERPROFILE", "") or str(Path.home()))
        if profile.exists():
            scanned = 0
            for root, dirs, files in os.walk(profile):
                scanned += 1
                if scanned > 2500:
                    break
                dirs[:] = [
                    d for d in dirs
                    if d.lower() not in {"appdata", ".git", "node_modules", "windows", "program files", "program files (x86)"}
                ]
                if Path(root).name.lower() == "my games":
                    add_logs_dir(Path(root) / "Rocket League" / "TAGame" / "Logs")
    except Exception:
        pass

    try:
        existing_first = sorted(
            [p for p in candidates if p.exists() and p.is_file()],
            key=lambda x: x.stat().st_mtime,
            reverse=True,
        )
        missing = [p for p in candidates if not (p.exists() and p.is_file())]
        ordered = existing_first + missing
    except Exception:
        ordered = candidates

    try:
        _LAUNCH_LOG_DISCOVERY_CACHE["ts"] = now
        _LAUNCH_LOG_DISCOVERY_CACHE["paths"] = [str(p) for p in ordered]
    except Exception:
        pass
    return ordered


def _candidate_rocket_league_launch_log_paths() -> List[Path]:
    """Chemins probables du fichier Launch Rocket League.

    Sécurité playlist Beta 7.61_from_7.28 :
    on lit uniquement Reservation(... Playlist=XX ...) pour différencier
    ranked/casual/privé. Aucune détection Freeplay n'est faite via Launch.

    Beta 7.82 : le fichier Launch n'est plus supposé être uniquement dans
    OneDrive. L'app cherche My Games\\Rocket League\\TAGame\\Logs\\Launch*
    dans Documents, OneDrive, Documents Windows redirigé et les profils du PC.
    """
    candidates = _discover_launch_log_paths_targeted_scan()
    _cleanup_launch_backup_files_near_candidates(candidates)
    return candidates


def _cleanup_launch_backup_files_near_candidates(candidates: List[Path]) -> None:
    """Évite l'accumulation de Launch-backup*.txt/log dans le dossier Logs.

    L'app ne doit pas créer de nouveaux backups Launch. Si d'anciens backups
    existent déjà dans les dossiers candidats, on les supprime pour éviter qu'ils
    soient relus ou recréés en boucle par erreur.
    """
    seen_dirs: Set[str] = set()
    for candidate in list(candidates or []):
        try:
            folder = Path(candidate).parent
            key = str(folder.resolve()).lower() if folder.exists() else str(folder).lower()
            if key in seen_dirs:
                continue
            seen_dirs.add(key)
            if not folder.exists():
                continue
            for pattern in ("Launch-backup*", "Launch_backup*", "Launch.backup*"):
                for backup_path in folder.glob(pattern):
                    try:
                        if backup_path.is_file():
                            backup_path.unlink()
                    except Exception:
                        pass
        except Exception:
            pass


def _read_launch_tail_text(path: Path, max_bytes: int = 900_000) -> str:
    try:
        size = path.stat().st_size
        with path.open("rb") as f:
            if size > max_bytes:
                f.seek(max(0, size - max_bytes))
            raw = f.read(max_bytes)
        for enc in ("utf-8", "utf-16", "utf-16-le", "cp1252", "latin-1"):
            try:
                return raw.decode(enc, errors="ignore")
            except Exception:
                continue
        return raw.decode("utf-8", errors="ignore")
    except Exception:
        return ""


def _launch_line_is_replay_start(line: str) -> bool:
    """Détecte une navigation Launch vers la lecture d'un replay Rocket League.

    Le mot ``replay`` est obligatoire. On exige aussi un indice de navigation/lecture
    afin de ne pas confondre un simple log de sauvegarde automatique de replay avec
    l'ouverture réelle d'un replay.
    """
    text = str(line or "").strip().casefold()
    if "replay" not in text:
        return False
    strong_hints = (
        "devnet: browse", "browse:", "gameinfo_replay", "?replay=", "replay_ta",
    )
    if any(hint in text for hint in strong_hints):
        return True
    # Fallback prudent pour les variantes de Launch : on accepte une ligne de
    # navigation/chargement contenant replay, mais pas les messages Save/Autosave.
    if any(word in text for word in ("browse", "travel", "loadmap", "open", "game=")):
        if not any(word in text for word in ("savereplay", "save replay", "saving replay", "autosave")):
            return True
    return False


