class ContextHelpOverlay(QFrame):
    """Pop-up d'aide moderne, alignée visuellement sur la fenêtre Discord."""

    def __init__(self, parent: QWidget, title: str, body: str) -> None:
        super().__init__(parent)
        self._blur_target: Optional[QWidget] = None
        self._previous_effect: Optional[Any] = None
        self.setObjectName("ContextHelpOverlay")
        self.setAttribute(Qt.WidgetAttribute.WA_StyledBackground, True)
        self.setStyleSheet("""
            QFrame#ContextHelpOverlay{background:rgba(5,7,12,.66);}
            QFrame#ContextHelpCard{background:rgba(15,20,34,.96);border:1px solid rgba(255,255,255,.10);border-radius:30px;}
            QLabel#ContextHelpIcon{color:#061525;background:#7DD3FC;border:1px solid rgba(165,227,255,.90);border-radius:27px;font-family:Montserrat,Segoe UI,Arial,sans-serif;font-size:28px;font-weight:1000;}
            QLabel#ContextHelpTitle{color:#FFFFFF;background:transparent;font-family:Montserrat,Segoe UI,Arial,sans-serif;font-size:23px;font-weight:1000;}
            QLabel#ContextHelpText{color:#B8C2D8;background:transparent;font-family:Montserrat,Segoe UI,Arial,sans-serif;font-size:13px;font-weight:760;line-height:1.42;}
            QPushButton#ContextHelpClose{background:#7DD3FC;color:#061525;border:1px solid rgba(165,227,255,.85);border-radius:15px;padding:12px 20px;font-family:Montserrat,Segoe UI,Arial,sans-serif;font-size:13px;font-weight:1000;}
            QPushButton#ContextHelpClose:hover{background:#A5E3FF;border-color:#FFFFFF;}
            QPushButton#ContextHelpClose:pressed{background:#38BDF8;}
        """)
        self._apply_parent_blur()

        outer = QGridLayout(self)
        outer.setContentsMargins(28, 28, 28, 28)
        outer.setAlignment(Qt.AlignmentFlag.AlignCenter)

        card_frame = QFrame(self)
        card_frame.setObjectName("ContextHelpCard")
        card_frame.setFixedWidth(560)
        card_layout = QVBoxLayout(card_frame)
        card_layout.setContentsMargins(34, 32, 34, 30)
        card_layout.setSpacing(15)
        card_layout.setAlignment(Qt.AlignmentFlag.AlignCenter)

        icon = QLabel("?", card_frame)
        icon.setObjectName("ContextHelpIcon")
        icon.setFixedSize(56, 56)
        icon.setAlignment(Qt.AlignmentFlag.AlignCenter)
        card_layout.addWidget(icon, alignment=Qt.AlignmentFlag.AlignCenter)

        title_label = QLabel(title or "Information", card_frame)
        title_label.setObjectName("ContextHelpTitle")
        title_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        title_label.setWordWrap(True)
        title_label.setFixedWidth(492)
        card_layout.addWidget(title_label)

        body_label = QLabel(body or "", card_frame)
        body_label.setObjectName("ContextHelpText")
        body_label.setWordWrap(True)
        body_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
        body_label.setFixedWidth(492)
        body_label.setMinimumHeight(54)
        card_layout.addWidget(body_label)

        close_btn = QPushButton("OK", card_frame)
        close_btn.setObjectName("ContextHelpClose")
        close_btn.setCursor(Qt.CursorShape.PointingHandCursor)
        close_btn.setFixedWidth(180)
        close_btn.clicked.connect(self.close)
        card_layout.addWidget(close_btn, alignment=Qt.AlignmentFlag.AlignCenter)

        outer.addWidget(card_frame, 0, 0)

    def _apply_parent_blur(self) -> None:
        parent = self.parentWidget()
        try:
            target = parent.centralWidget() if isinstance(parent, QMainWindow) else parent
            if target is None:
                return
            current = target.graphicsEffect()
            if current is not None:
                self._previous_effect = current
            effect = QGraphicsBlurEffect(target)
            effect.setBlurRadius(4.0)
            target.setGraphicsEffect(effect)
            self._blur_target = target
        except Exception:
            self._blur_target = None
            self._previous_effect = None

    def _clear_parent_blur(self) -> None:
        try:
            if self._blur_target is not None:
                self._blur_target.setGraphicsEffect(self._previous_effect)
        except Exception:
            pass
        self._blur_target = None
        self._previous_effect = None

    def closeEvent(self, event: Any) -> None:  # noqa: N802
        self._clear_parent_blur()
        try:
            parent = self.parentWidget()
            if parent is not None and getattr(parent, "_context_help_overlay", None) is self:
                parent._context_help_overlay = None
        except Exception:
            pass
        try:
            super().closeEvent(event)
        except Exception:
            pass

    def keyPressEvent(self, event: Any) -> None:  # noqa: N802
        try:
            if event.key() == Qt.Key.Key_Escape:
                self.close()
                return
        except Exception:
            pass
        try:
            super().keyPressEvent(event)
        except Exception:
            pass


def _show_context_help_popup(title: str, body: str) -> None:
    """Affiche les sous-textes des blocs dans une pop-up moderne avec fond assombri/flouté."""
    try:
        parent = QApplication.activeWindow()
    except Exception:
        parent = None

    try:
        translator = getattr(parent, "_translate_text_value", None) if parent is not None else None
        display_title = translator(str(title or "Information")) if callable(translator) else str(title or "Information")
        display_body = translator(str(body or "")) if callable(translator) else str(body or "")
    except Exception:
        display_title = str(title or "Information")
        display_body = str(body or "")

    if isinstance(parent, QWidget):
        try:
            previous = getattr(parent, "_context_help_overlay", None)
            if previous is not None:
                previous.close()
        except Exception:
            pass
        overlay = ContextHelpOverlay(parent, display_title, display_body)
        overlay.setGeometry(parent.rect())
        overlay.show()
        overlay.raise_()
        overlay.setFocus(Qt.FocusReason.PopupFocusReason)
        try:
            parent._context_help_overlay = overlay
        except Exception:
            pass
        return

    box = QMessageBox(parent)
    box.setIcon(QMessageBox.Icon.Information)
    box.setWindowTitle(display_title)
    box.setText(display_title)
    box.setInformativeText(display_body)
    box.setStandardButtons(QMessageBox.StandardButton.Ok)
    box.exec()


def help_button(title: str, body: str) -> QPushButton:
    btn = QPushButton("?")
    btn.setObjectName("CardHelpButton")
    btn.setFixedSize(23, 23)
    btn.setCursor(Qt.CursorShape.PointingHandCursor)
    btn.setToolTip("Afficher l’aide de ce bloc")
    btn.setStyleSheet(
        "QPushButton#CardHelpButton{background:#7DD3FC;color:#061525;border:1px solid rgba(165,227,255,.75);"
        "border-radius:11px;padding:0;font-size:13px;font-weight:1000;}"
        "QPushButton#CardHelpButton:hover{background:#A5E3FF;border-color:#FFFFFF;}"
        "QPushButton#CardHelpButton:pressed{background:#38BDF8;}"
    )
    btn.clicked.connect(lambda _=False, t=title, b=body: _show_context_help_popup(t, b))
    return btn


def card(title: str = "", subtitle: str = "") -> QFrame:
    frame = QFrame()
    frame.setStyleSheet(
        "QFrame { background: #111521; border: none; border-radius: 16px; }"
    )
    layout = QVBoxLayout(frame)
    layout.setContentsMargins(12, 10, 12, 10)
    layout.setSpacing(6)
    # Beta 6.56 : les titres/textes restent collés en haut de leur bloc,
    # même dans les cartes plus hautes des réglages.
    layout.setAlignment(Qt.AlignmentFlag.AlignTop)
    if title:
        lab = QLabel(title.upper())
        lab.setAlignment(Qt.AlignmentFlag.AlignTop | Qt.AlignmentFlag.AlignLeft)
        lab.setStyleSheet("color:#8C96AC;font-size:10px;font-weight:800;letter-spacing:1.3px;background:transparent;")
        if subtitle:
            title_row = QHBoxLayout()
            title_row.setContentsMargins(0, 0, 0, 0)
            title_row.setSpacing(8)
            title_row.addWidget(lab, 0, Qt.AlignmentFlag.AlignVCenter)
            title_row.addStretch(1)
            title_row.addWidget(help_button(title, subtitle), 0, Qt.AlignmentFlag.AlignVCenter)
            layout.addLayout(title_row)
        else:
            layout.addWidget(lab)
    elif subtitle:
        helper_row = QHBoxLayout()
        helper_row.setContentsMargins(0, 0, 0, 0)
        helper_row.addStretch(1)
        helper_row.addWidget(help_button("Information", subtitle), 0, Qt.AlignmentFlag.AlignVCenter)
        layout.addLayout(helper_row)
    # Beta 7.95 : les sous-textes ne sont plus affichés en permanence.
    # Ils sont déplacés dans le bouton rond "?" pour alléger visuellement l'application.
    return frame


