def make_copy_button_icon() -> QIcon:
    """Charge l'asset fourni et le teinte comme le texte du bouton."""
    source = QPixmap(str(COPY_ICON_PNG))
    if source.isNull():
        return QIcon()

    def tinted(color: QColor) -> QPixmap:
        scaled = source.scaled(
            QSize(16, 16),
            Qt.AspectRatioMode.KeepAspectRatio,
            Qt.TransformationMode.SmoothTransformation,
        )
        result = QPixmap(QSize(16, 16))
        result.fill(Qt.GlobalColor.transparent)
        painter = QPainter(result)
        try:
            x = (result.width() - scaled.width()) // 2
            y = (result.height() - scaled.height()) // 2
            painter.drawPixmap(x, y, scaled)
            painter.setCompositionMode(QPainter.CompositionMode.CompositionMode_SourceIn)
            painter.fillRect(result.rect(), color)
        finally:
            painter.end()
        return result

    icon = QIcon()
    icon.addPixmap(tinted(QColor("#FFFFFF")), QIcon.Mode.Normal, QIcon.State.Off)
    icon.addPixmap(tinted(QColor("#7B8498")), QIcon.Mode.Disabled, QIcon.State.Off)
    return icon


def apply_copy_button_icon(button: QPushButton) -> None:
    button.setIcon(make_copy_button_icon())
    button.setIconSize(QSize(16, 16))


def make_visibility_icon(is_visible: bool) -> QIcon:
    """Crée une icône œil ouvert / œil barré sans dépendance externe."""
    pix = QPixmap(30, 30)
    pix.fill(Qt.GlobalColor.transparent)

    painter = QPainter(pix)
    painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)

    white = QColor("#FFFFFF")
    soft = QColor("#DCEBFF")

    eye_path = QPainterPath()
    eye_path.moveTo(3, 15)
    eye_path.cubicTo(8, 7, 22, 7, 27, 15)
    eye_path.cubicTo(22, 23, 8, 23, 3, 15)

    pen = QPen(soft, 2.4)
    pen.setCapStyle(Qt.PenCapStyle.RoundCap)
    pen.setJoinStyle(Qt.PenJoinStyle.RoundJoin)

    painter.setPen(pen)
    painter.setBrush(Qt.BrushStyle.NoBrush)
    painter.drawPath(eye_path)

    painter.setPen(Qt.PenStyle.NoPen)
    painter.setBrush(QBrush(white))
    painter.drawEllipse(QRect(12, 12, 6, 6))

    if not is_visible:
        slash_pen = QPen(white, 3.1)
        slash_pen.setCapStyle(Qt.PenCapStyle.RoundCap)
        painter.setPen(slash_pen)
        painter.setBrush(Qt.BrushStyle.NoBrush)
        painter.drawLine(6, 24, 24, 6)

    painter.end()
    return QIcon(pix)


def apply_visibility_button_icon(button: QPushButton, is_visible: bool) -> None:
    """Applique l'icône de visibilité au bouton sans changer son comportement."""
    button.setIcon(make_visibility_icon(is_visible))
    button.setIconSize(QSize(22, 22))


