    def _device_name_for_gamepad_config(self, backend: str, controller_index: int) -> str:
        try:
            backend = str(backend or "xinput").lower()
            idx = int(controller_index or 0)
            if backend == "winmm":
                # Beta 7.61 : ne jamais appeler joyGetDevCapsW pour obtenir le nom.
                return _winmm_device_name(idx)
            if backend == "xinput":
                return f"Xbox/XInput {idx}"
            for item in enumerate_connected_gamepads():
                if str(item.get("backend") or "").lower() == backend and int(item.get("index", -1) or -1) == idx:
                    return str(item.get("name") or "")
        except Exception:
            pass
        return ""

    def _label_for_gamepad_button_key(self, key: str, backend: str = "xinput") -> str:
        try:
            if not str(key or "").strip():
                return self._translate_text_value("Aucune touche")
            cfg = self._players_mmr_overlay_config()
            idx = int(cfg.get("controller_index", 0) or 0)
            device_name = self._device_name_for_gamepad_config(backend, idx)
            return gamepad_input_label(backend, key, device_name)
        except Exception:
            return self._translate_text_value("Aucune touche")

