    def _make_percent_slider(self, value: int, minimum: int, maximum: int, on_change: Callable[[int], None]) -> Tuple[QSlider, QLabel]:
        slider = QSlider(Qt.Orientation.Horizontal)
        slider.setRange(int(minimum), int(maximum))
        slider.setSingleStep(1)
        slider.setPageStep(5)
        slider.setValue(max(int(minimum), min(int(maximum), int(value))))
        value_label = QLabel(f"{slider.value()} %")
        value_label.setMinimumWidth(52)
        value_label.setAlignment(Qt.AlignmentFlag.AlignRight | Qt.AlignmentFlag.AlignVCenter)
        value_label.setStyleSheet("color:#FFFFFF;font-size:12px;font-weight:900;background:transparent;")
        slider.valueChanged.connect(lambda v: (value_label.setText(f"{int(v)} %"), on_change(int(v))))
        return slider, value_label

    def _tiktok_coming_soon_label(self) -> QLabel:
        # Conservé uniquement en compatibilité interne. Depuis la Beta 6.98,
        # les textes rouges TikTok ne sont plus affichés dans l'interface.
        label = QLabel("")
        label.setVisible(False)
        return label

    def _add_link_mode_items_with_disabled_tiktok(self, combo: QComboBox) -> None:
        # Nom conservé pour compatibilité interne : TikTok est réactivé pour tests.
        combo.addItem(self._translate_text_value("Lien OBS réseau"), "obs")
        combo.addItem(self._translate_text_value("Lien TikTok Live Studio 👑"), "tiktok")
        try:
            item = combo.model().item(1)
            if item is not None:
                item.setEnabled(True)
                item.setToolTip("")
                item.setForeground(QBrush(QColor("#FFD166")))
        except Exception:
            pass
        combo.setToolTip("")

