    def _selected_overlay_mode(self) -> str:
        combo = getattr(self, "overlay_type_combo", None)
        if combo is not None:
            mode = str(combo.currentData() or "banner")
        else:
            mode = str(self.config["theme"].get("mode", "banner") or "banner")
        return mode if mode in {"banner", "vertical", "horizontal", "premium_tower"} else "banner"

    def _on_overlay_type_changed(self, *_: Any) -> None:
        mode = self._selected_overlay_mode()
        if mode in {"vertical", "horizontal", "premium_tower"} and not self._is_discord_premium_verified():
            self._refresh_premium_overlay_access_ui()
            self._log("Overlay Premium verrouillé · rôle Premium Discord requis")
            return
        # Beta 7.94 : avant de changer le type, on sauvegarde le coin visible réel.
        # Le point affiché reste fixe même si la taille invisible WebEngine change.
        if self._is_game_overlay_direct_active():
            try:
                window = getattr(self, "game_overlay_windows", {}).get("main")
                if window is not None:
                    origin = window.visual_origin()
                    cfg = self._game_overlay_config()
                    cfg["main_pos"] = [int(origin.x()), int(origin.y())]
                    cfg["main_pos_relative"] = False
                    cfg["main_pos_visual_box"] = True
                    self.config.save()
            except Exception:
                pass
        previous_mode = str(self.config["theme"].get("mode", "banner") or "banner")
        theme_patch = {"mode": mode}
        # Beta 8.02 : La tour premium est plus haute par design, donc sa taille
        # de départ est 80 % quand on la sélectionne pour éviter qu'elle sorte de l'écran.
        if mode == "premium_tower" and previous_mode != "premium_tower":
            theme_patch["scale"] = 80
        self.update_theme(theme_patch)
        if "scale" in theme_patch:
            try:
                if hasattr(self, "scale_spin"):
                    self.scale_spin.blockSignals(True)
                    self.scale_spin.setValue(int(theme_patch["scale"]))
                    self.scale_spin.blockSignals(False)
            except Exception:
                pass
        if self._is_game_overlay_direct_active():
            self._set_direct_overlay_scale(True)
            for window in getattr(self, "game_overlay_windows", {}).values():
                try:
                    window.update_state(self.get_public_state())
                    window.reload_overlay()
                except Exception:
                    pass
        label = "bannière classique" if mode == "banner" else "vertical compact" if mode == "vertical" else "horizontal compact" if mode == "horizontal" else "La tour premium"
        self._log(f"Type d’overlay principal sélectionné : {label}")

