    def set_ingame_quick_menu_enabled(self, enabled: bool) -> None:
        """Affiche ou détruit proprement le dock sans redémarrer l'application."""
        enabled = bool(enabled)
        self.config.data["ingame_quick_menu_enabled"] = enabled
        self.config.save()
        if enabled:
            if getattr(self, "ingame_quick_menu", None) is None:
                self._init_ingame_quick_menu()
            self._sync_ingame_quick_menu()
        else:
            menu = getattr(self, "ingame_quick_menu", None)
            if menu is not None:
                try:
                    menu.dispose()
                    menu.deleteLater()
                except Exception:
                    pass
                self.ingame_quick_menu = None
        self._log(
            "Menu dock rétractable : affiché" if enabled
            else "Menu dock rétractable : masqué"
        )

    def set_count_casual_results(self, enabled: bool) -> None:
        self.config["count_casual_results"] = bool(enabled)
        self.config.save()
        self._log("Comptage Win/Lose Casual : " + ("activé" if enabled else "désactivé"))

