    def _apply_stable_autostart_settings(self, source: str = "startup") -> Dict[str, bool]:
        # Beta 7.61 : suppression complète du watcher "lancer quand Rocket League s'ouvre".
        # On conserve uniquement l'option de lancement au démarrage du PC et on nettoie
        # les anciennes entrées watcher qui auraient été installées par les versions précédentes.
        try:
            self.config.data.pop("rl_autostart_watcher_enabled", None)
        except Exception:
            pass
        results = install_stable_autostart_system(
            windows_startup=bool(self.config.get("windows_startup_enabled", True)),
        )
        try:
            self._log(
                "Auto-start Windows : "
                + ("PC OK" if results.get("windows_startup") else "PC désactivé/indisponible")
                + " · Watcher Rocket League supprimé"
                + f" · {source}"
            )
        except Exception:
            pass
        return results

    def set_windows_startup_enabled(self, enabled: bool) -> None:
        self.config["windows_startup_enabled"] = bool(enabled)
        self.config.save()
        self._apply_stable_autostart_settings("option démarrage PC")

