    # ──────────────────────────────────────────────────────────────────────
    # State, publishing and UI refresh
    # ──────────────────────────────────────────────────────────────────────

    def get_public_state(self) -> Dict[str, Any]:
        with self.lock:
            try:
                # `showmatch_visible` n'existe pas dans l'état : la vraie valeur est
                # `showmatch_enabled`. L'ancien test empêchait la synchro des pseudos/teams
                # quand le Showmatch était affiché dans OBS.
                if getattr(self.state, "showmatch_enabled", False):
                    self._ensure_showmatch_names_locked()
            except Exception:
                pass
            public = self.state.to_dict(self.config["theme"])
            public["language"] = self._language()
            direct_active = self._is_game_overlay_direct_active()
            public["game_overlay_direct_active"] = direct_active
            public["obs_overlays_suspended"] = direct_active
            public["remote_key"] = self.config.get("remote_key", "")
            try:
                ov = public.get("players_mmr_overlay")
                if isinstance(ov, dict):
                    ov["streamer_anonymize"] = bool(self.config.get("streamer_anonymize_players_mmr", False))
                    ov["players"] = self._players_mmr_overlay_display_players(
                        [dict(p) for p in list(ov.get("players") or []) if isinstance(p, dict)]
                    )
            except Exception:
                pass
            public["http_port"] = HTTP_PORT
            public["ws_port"] = WS_PORT
            public["ws_clients"] = len(self.hub.ws_clients)
            public["rls_mmr_api_status"] = self._rls_mmr_api_status()
            return public

    def _publish_state(self, count_revision: bool = True) -> None:
        try:
            if not self._is_discord_access_verified():
                return
            # Le heartbeat de publication répare aussi le listener local si
            # son thread s'est arrêté après une erreur système inattendue.
            try:
                self.hub.ensure_running()
            except Exception:
                pass
            # Beta 8.45 : les Browser Sources dépendent désormais du relais LAN.
            # S'il s'est arrêté après une erreur Windows/réseau, chaque publication
            # tente de le remettre en service sans toucher au serveur interne 49124.
            try:
                if not self.network_overlay_relay.is_running():
                    self.network_overlay_relay.start()
            except Exception:
                pass
            # Pendant le traitement d'une rafale StatsAPI, on retarde les broadcasts.
            if getattr(self, "_batching_api_events", False):
                self._pending_publish_revision = bool(self._pending_publish_revision or count_revision)
                return

            now = time.time()
            # Les publications sans révision sont des statuts/heartbeats : pas besoin
            # de rafraîchir OBS/UI plusieurs fois par seconde.
            if not count_revision and now - float(getattr(self, "_last_publish_monotonic", 0.0) or 0.0) < 0.20:
                return
            self._last_publish_monotonic = now

            with self.lock:
                if count_revision:
                    self.state.revision += 1
                self.state.last_publish_at = time.strftime("%H:%M:%S")
            state = self.get_public_state()
            try:
                self.hub.broadcast(state)
            except Exception as exc:
                self._log(f"Broadcast OBS/remote ignoré : {exc}")
            try:
                # Ne jamais manipuler les widgets directement depuis un thread API/WebSocket.
                self.signals.state_changed.emit(state)
            except Exception as exc:
                self._log(f"Signal UI ignoré : {exc}")
        except Exception as exc:
            try:
                self._log(f"Publication état ignorée : {exc}")
            except Exception:
                pass


    def _refresh_dashboard_api_statuses(self, state: Optional[Dict[str, Any]] = None) -> None:
        """Synchronise les deux pastilles placées sous le titre Dashboard."""
        try:
            payload = state if isinstance(state, dict) else {}
            stats_status = str(
                payload.get("connection")
                or getattr(getattr(self, "state", None), "connection", "disconnected")
                or "disconnected"
            ).strip().lower()
            english = self._language() == "en"
            stats_meta = {
                "connected": (
                    "available", "#23A55A",
                    "StatsAPI connected" if english else "StatsAPI connecté",
                ),
                "connecting": (
                    "unstable", "#F0B232",
                    "StatsAPI connection…" if english else "Connexion StatsAPI…",
                ),
                "error": (
                    "maintenance", "#F23F43",
                    "StatsAPI is not responding" if english else "StatsAPI ne répond pas",
                ),
                "disconnected": (
                    "offline", "#80848E",
                    "StatsAPI disconnected" if english else "StatsAPI déconnecté",
                ),
            }
            palette_key, stats_color, fallback_message = stats_meta.get(
                stats_status,
                stats_meta["disconnected"],
            )
            # Le Dashboard garde un libellé compact et stable. Les détails de
            # socket restent dans LOGS LIVE afin que la ligne et la bulle
            # Uiverse ne soient jamais coupées par un message technique long.
            stats_message = fallback_message
            stats_dot = getattr(self, "status_dot", None)
            stats_label = getattr(self, "status_text", None)
            if isinstance(stats_dot, DashboardApiStatusDot):
                stats_dot.setIndicator(palette_key, stats_color, stats_message)
            if stats_label is not None:
                stats_label.setText(stats_message)
                stats_label.setStyleSheet(
                    f"color:{stats_color};font-size:12px;font-weight:800;"
                    "background:transparent;padding:0;margin:0;"
                )

            mmr_status = str(
                payload.get("rls_mmr_api_status") or self._rls_mmr_api_status() or "available"
            ).strip().lower()
            if mmr_status not in RLSApiStatusDot.STATUS_META:
                mmr_status = "available"
            language = "en" if english else "fr"
            mmr_meta = RLSApiStatusDot.STATUS_META[mmr_status]
            mmr_label_text = {
                "available": "MMR API · Available" if english else "API MMR · Disponible",
                "unstable": "MMR API · Unstable" if english else "API MMR · Instable",
                "maintenance": "MMR API · Maintenance" if english else "API MMR · Maintenance",
                "offline": "MMR API · Offline" if english else "API MMR · Hors ligne",
            }[mmr_status]
            mmr_dot = getattr(self, "dashboard_mmr_api_status_dot", None)
            mmr_label = getattr(self, "dashboard_mmr_api_status_text", None)
            if isinstance(mmr_dot, RLSApiStatusDot):
                mmr_dot.setStatus(mmr_status, language)
            if mmr_label is not None:
                mmr_label.setText(mmr_label_text)
                mmr_label.setStyleSheet(
                    f"color:{mmr_meta['color']};font-size:12px;font-weight:800;"
                    "background:transparent;padding:0;margin:0;"
                )
        except Exception:
            pass

    def _refresh_dashboard_premium_player_style(self) -> None:
        """Affiche le pseudo détecté en Gold lumineux pour les membres Premium."""
        try:
            label = getattr(self, "player_label", None)
            if label is None:
                return
            has_player = str(label.text() or "").strip() not in {"", "—", "-"}
            premium = bool(has_player and self._is_discord_premium_verified())
            label.setStyleSheet(
                (
                    "color:#FFD76A;font-size:24px;font-weight:1000;background:transparent;"
                    "font-family:'Montserrat','Segoe UI',Arial,sans-serif;"
                )
                if premium
                else "color:#F6F8FF;font-size:24px;font-weight:900;background:transparent;"
            )
            effect = getattr(self, "dashboard_player_gold_effect", None)
            if effect is not None:
                effect.setEnabled(premium)
        except Exception:
            pass

    def _refresh_ui(self, state: Dict[str, Any]) -> None:
        self.player_label.setText(state.get("player") or "—")
        self._refresh_dashboard_premium_player_style()
        self._refresh_dashboard_api_statuses(state)
        self.playlist_label.setText(self._translate_text_value(f"Playlist : {state.get('playlist_name') or 'Aucune'}"))
        if hasattr(self, "playlist_combo"):
            combo_playlist = str(state.get("playlist") or "")
            combo_text = combo_playlist if combo_playlist in PLAYLIST_NAMES else NO_PLAYLIST_LABEL
            if self.playlist_combo.currentText() != combo_text:
                self.playlist_combo.blockSignals(True)
                self.playlist_combo.setCurrentText(combo_text)
                self.playlist_combo.blockSignals(False)
        self.last_event_label.setText(state.get("last_event") or "—")
        self.last_event_at_label.setText(self._translate_text_value(state.get("last_event_at") or "En attente d'événement"))
        self.stat_labels["wins"].setText(str(state.get("wins", 0)))
        self.stat_labels["losses"].setText(str(state.get("losses", 0)))
        sv = state.get("streak_val", 0)
        st = state.get("streak_type")
        self.stat_labels["streak"].setText(f"{sv}{'W' if st == 'win' else 'L' if st == 'loss' else ''}" if sv else "—")
        mmr = state.get("mmr")
        delta = state.get("mmr_change", 0)
        rank = state.get("rank") or ""
        rank_short = state.get("rank_short") or ""
        mmr_text = (f"{mmr} ({delta:+})" if delta else str(mmr)) if mmr else "—"
        self.stat_labels["mmr"].setText(f"{mmr_text} · {rank_short or rank}" if rank and mmr else mmr_text)
        if hasattr(self, "dashboard_rls_error_icon"):
            try:
                # Beta 7.02 : affichage strictement piloté par les erreurs du MMR principal.
                # Le texte tracker_status peut contenir des erreurs/infos d'appels secondaires
                # et ne doit donc plus contrôler cette icône.
                rls_error = bool(state.get("rls_api_error_active", False))
                tooltip = self._translate_text_value("L'API détection MMR est en maintenance.")
                detail = str(state.get("rls_api_error_message", "") or "").strip()
                # Beta 7.03 : l'icône est un enfant absolu du petit bloc MMR.
                # On la repositionne à chaque refresh car la largeur du bloc est
                # connue seulement après le layout Qt.
                card = getattr(self, "dashboard_mmr_card", None)
                if card is not None:
                    try:
                        self.dashboard_rls_error_icon.move(max(4, int(card.width()) - 42), 8)
                    except Exception:
                        pass
                self.dashboard_rls_error_icon.setVisible(rls_error)
                self.dashboard_rls_error_icon.raise_()
                self.dashboard_rls_error_icon.setToolTip(tooltip if not detail else tooltip + "\n" + detail)
                try:
                    if rls_error and self.dashboard_rls_error_anim is not None and self.dashboard_rls_error_anim.state() != QAbstractAnimation.State.Running:
                        self.dashboard_rls_error_anim.start()
                    elif (not rls_error) and self.dashboard_rls_error_anim is not None and self.dashboard_rls_error_anim.state() == QAbstractAnimation.State.Running:
                        self.dashboard_rls_error_anim.stop()
                except Exception:
                    pass
            except Exception:
                pass
        score = state.get("score", {})
        self.stat_labels["score"].setText(f"{score.get('me', 0)} - {score.get('opponent', 0)}")
        if hasattr(self, "main_overlay_toggle_btn"):
            main_visible = bool(state.get("main_overlay_enabled", True))
            self.main_overlay_toggle_btn.setText(self._translate_text_value("Masquer Win/Lose" if main_visible else "Afficher Win/Lose"))
            apply_visibility_button_icon(self.main_overlay_toggle_btn, main_visible)
        if hasattr(self, "sidebar_showmatch_toggle_btn"):
            sm_state = state.get("showmatch", {}) or {}
            self.sidebar_showmatch_toggle_btn.setText(self._translate_text_value("Masquer Showmatch" if sm_state.get("enabled") else "Afficher Showmatch"))

            apply_visibility_button_icon(self.sidebar_showmatch_toggle_btn, bool(sm_state.get("enabled")))
        if hasattr(self, "showmatch_status_label"):
            sm = state.get("showmatch", {}) or {}
            status = f"Showmatch {sm.get('game_label', 'BO')} · {sm.get('left_name', 'Player')} {sm.get('left_score', 0)} - {sm.get('right_score', 0)} {sm.get('right_name', 'Opponent')}"
            if not sm.get("enabled"):
                status = self._translate_text_value("Showmatch masqué")
            elif sm.get("completed"):
                status += self._translate_text_value(" · terminé")
            self.showmatch_status_label.setText(status)
            if hasattr(self, "showmatch_toggle_btn"):
                self.showmatch_toggle_btn.setText(self._translate_text_value("Masquer Showmatch" if sm.get("enabled") else "Afficher Showmatch"))
            if hasattr(self, "showmatch_game_spin"):
                current_game = int(sm.get("current_game", 1) or 1)
                bo = int(sm.get("bo", 5) or 5)
                self.showmatch_game_spin.blockSignals(True)
                self.showmatch_game_spin.setRange(1, bo)
                self.showmatch_game_spin.setValue(max(1, min(current_game, bo)))
                self.showmatch_game_spin.blockSignals(False)
        self._update_game_overlay_windows(state)
        direct_active = bool(state.get("game_overlay_direct_active", False))
        for widget_name in (
            "main_overlay_toggle_btn",
            "sidebar_showmatch_toggle_btn",
            "showmatch_toggle_btn",
            "showmatch_bo_combo",
            "showmatch_game_spin",
            "showmatch_left_edit",
            "showmatch_right_edit",
            "showmatch_add_left_btn",
            "showmatch_add_right_btn",
            "showmatch_reset_btn",
            "showmatch_undo_btn",
        ):
            widget = getattr(self, widget_name, None)
            if widget is not None:
                try:
                    widget.setEnabled(not direct_active)
                    widget.setToolTip(
                        self._translate_text_value("Désactivé temporairement : l'overlay direct sur le jeu est actif.")
                        if direct_active else ""
                    )
                except Exception:
                    pass
        if hasattr(self, "showmatch_status_label") and direct_active:
            self.showmatch_status_label.setText(self._translate_text_value("Showmatch OBS désactivé pendant l'overlay direct jeu"))

        raw = state.get("last_raw_event") or self.state.last_raw_event
        if raw and hasattr(self, "raw_box"):
            try:
                raw_text = json.dumps(raw, ensure_ascii=False, separators=(",", ":"))[:5000]
            except Exception:
                raw_text = str(raw)[:5000]
            if raw_text != getattr(self, "_last_raw_box_text", ""):
                self._last_raw_box_text = raw_text
                self.raw_box.setPlainText(raw_text)
        if hasattr(self, "ingame_quick_menu_enabled_cb"):
            try:
                dock_enabled = bool(self.config.get("ingame_quick_menu_enabled", False))
                if self.ingame_quick_menu_enabled_cb.isChecked() != dock_enabled:
                    self.ingame_quick_menu_enabled_cb.blockSignals(True)
                    self.ingame_quick_menu_enabled_cb.setChecked(dock_enabled)
                    self.ingame_quick_menu_enabled_cb.blockSignals(False)
            except Exception:
                pass
        self._apply_language_to_ui()
        try:
            self._refresh_manual_rls_test_access_ui()
        except Exception:
            pass

    def _on_status(self, status: str, message: str) -> None:
        self._refresh_dashboard_api_statuses(
            {
                "connection": status,
                "connection_message": message,
                "rls_mmr_api_status": self._rls_mmr_api_status(),
            }
        )
        saved_player = ""
        with self.lock:
            previous_status = str(self.state.connection or "")
            self.state.connection = status
            self.state.connection_message = message

            if status == "connected":
                # On arme une seule sauvegarde pour cette connexion API. Les boucles
                # de reconnexion sans connexion réelle ne créent pas de sauvegardes vides.
                self._api_connected_since_last_disconnect_save = True
            elif status == "disconnected" and self._api_connected_since_last_disconnect_save:
                # Toujours sauvegarder avant de nettoyer l'état courant : on garde
                # la session terminée dans les sauvegardes, puis l'app revient à zéro
                # pour accueillir le prochain compte / la prochaine session StatsAPI.
                saved_player = self._auto_save_current_player_on_api_disconnect_locked()
                self._reset_runtime_session_after_statsapi_disconnect_locked()
                self._api_connected_since_last_disconnect_save = False
            elif status == "disconnected":
                self._reset_runtime_session_after_statsapi_disconnect_locked()
            elif status in {"error", "connecting"} and previous_status != "connected":
                # Pas de sauvegarde si l'API n'a jamais été connectée depuis le dernier essai.
                pass

        if saved_player:
            self._refresh_session_ui()
            self._log(f"API déconnectée : sauvegarde automatique de {saved_player} écrasée/mise à jour")
            self._log("Session courante réinitialisée : stats, joueur, playlist et API RLS remis à zéro")
        if status == "disconnected":
            self._sync_tracker_inputs_from_config()
        self._maybe_show_statsapi_connection_help(status, message)
        # Le comptage Showmatch est fait dans _handle_match_ended /
        # _handle_match_destroyed_by_score. Ne rien recompter ici : cette méthode
        # reçoit seulement les changements de statut de connexion.
        self._publish_state()


