    def _detected_player_primary_identity_locked(self, *payloads: Any) -> Tuple[str, str, str]:
        """Retourne /{platform}/{PrimaryId} du joueur qui correspond au pseudo détecté.

        Sécurité MMR : on ne doit jamais utiliser le premier joueur du JSON si un
        pseudo local est déjà détecté. On cherche d'abord le joueur dont le nom/ID
        correspond au pseudo affiché dans l'application, puis on extrait son
        PrimaryId pour l'API RLS.
        """
        manual_platform, manual_player, manual_reason = self._manual_rls_test_identity_locked()
        if manual_player:
            return manual_platform, manual_player, manual_reason

        session_platform, session_primary_id, session_reason = self._get_freeplay_session_identity_locked()
        if session_primary_id:
            return session_platform, session_primary_id, session_reason

        detected_hint = str(getattr(self.state, "detected_player_name", "") or "").strip()
        if not detected_hint:
            return "", "", "pseudo détecté absent"

        candidate_collections: List[Any] = []
        current_players = list(getattr(self.state, "current_players", []) or [])
        if current_players:
            candidate_collections.append(current_players)

        for payload in payloads:
            try:
                players = extract_players_collection(payload)
                if players:
                    candidate_collections.append(players)
            except Exception:
                continue

        seen_keys: set = set()
        for players in candidate_collections:
            player = find_player_by_identity_hint(players, detected_hint)
            if not isinstance(player, dict):
                continue

            try:
                primary_id = extract_primary_id_from_player_obj(player)
            except Exception:
                primary_id = ""
            primary_id = str(primary_id or "").strip()
            if not primary_id:
                continue

            key = primary_id.casefold()
            if key in seen_keys:
                continue
            seen_keys.add(key)

            platform = tracker_platform_from_primary_id(player, primary_id, "auto")
            platform = self._normalize_tracker_platform(platform).lower()
            if platform == "auto":
                platform = "steam" if re.fullmatch(r"\d{15,20}", primary_id) else "epic"

            platform, clean_primary_id, _endpoint = self._normalize_rls_saved_endpoint_locked(platform, primary_id)
            if clean_primary_id:
                return platform, clean_primary_id, "ID joueur confirmé par pseudo détecté"

        return "", "", "aucun PrimaryId ne correspond au pseudo détecté"

