    def update_theme(self, patch: Dict[str, Any]) -> None:
        theme = dict(self.config["theme"])
        # Beta 8.03 : Afficher MMR n'est plus une option utilisateur.
        # On ignore les anciennes commandes/remote et on force l'affichage.
        patch = {k: v for k, v in dict(patch).items() if k not in {"radius", "show_mmr"}}
        if str(patch.get("mode") or "") == "premium_tower" and not self._is_discord_premium_verified():
            self._log("La tour premium verrouillée · rôle Premium Discord requis")
            self._refresh_premium_overlay_access_ui()
            return
        if "opacity" in patch:
            try:
                patch["opacity"] = max(15, min(100, int(patch["opacity"])))
            except Exception:
                patch["opacity"] = 100
        if "scale" in patch:
            try:
                patch["scale"] = max(30, min(180, int(patch["scale"])))
            except Exception:
                patch["scale"] = int(theme.get("scale", 100) or 100)
        if "mmr_popup_position" in patch:
            patch["mmr_popup_position"] = str(patch.get("mmr_popup_position") or "bottom").lower()
            if patch["mmr_popup_position"] not in {"top", "right", "left", "bottom"}:
                patch["mmr_popup_position"] = "bottom"
        if str(patch.get("mode") or "") == "premium_tower":
            try:
                with self.lock:
                    self.state.main_rankup_popup_preview_visible = False
                    self.state.main_rankup_popup_preview_started_at = 0.0
                    self.state.main_rankup_popup_preview_until = 0.0
                    self.state.mmr_rankup_popup_visible = False
                    self.state.mmr_rankup_popup_started_at = 0.0
            except Exception:
                pass
        theme.update(patch)
        theme["radius"] = 20
        theme["bg"] = "rgba(8,10,16,.88)"
        theme["show_mmr"] = True
        theme.setdefault("opacity", 100)
        theme.setdefault("mmr_popup_position", "bottom")
        self.config["theme"] = theme
        try:
            if hasattr(self, "scale_value_label"):
                self.scale_value_label.setText(f"{int(theme.get('scale', 100) or 100)} %")
            if hasattr(self, "opacity_value_label"):
                self.opacity_value_label.setText(f"{int(theme.get('opacity', 100) or 100)} %")
            popup_pos = str(theme.get("mmr_popup_position", "bottom") or "bottom")
            for combo_attr in ("rankup_popup_position_combo", "obs_rankup_popup_position_combo"):
                combo = getattr(self, combo_attr, None)
                if combo is not None:
                    combo.blockSignals(True)
                    for i in range(combo.count()):
                        if combo.itemData(i) == popup_pos:
                            combo.setCurrentIndex(i)
                            break
                    combo.blockSignals(False)
            self._refresh_mmr_popup_position_access_ui()
        except Exception:
            pass
        try:
            if "scale" in patch and self._is_game_overlay_direct_active():
                self._game_overlay_config()["direct_scale"] = int(theme.get("scale", 100) or 100)
        except Exception:
            pass
        try:
            self.config.save()
        except Exception:
            pass
        self._publish_state()
        try:
            menu = getattr(self, "ingame_quick_menu", None)
            if menu is not None:
                menu.refresh_from_app()
        except Exception:
            pass

