    def _candidate_rl_config_dirs(self, platform: str = "all") -> List[Path]:
        """Détecte automatiquement les dossiers Rocket League TAGame\\Config.

        La détection ne dépend pas d'un chemin fixe Steam/Epic :
        - Documents Windows
        - Documents redirigés OneDrive
        - Bibliothèques Steam depuis libraryfolders.vdf
        - Manifestes Epic Games Launcher
        - chemins d'installation classiques en dernier recours
        """
        candidates: List[Path] = []

        def add_candidate(path: Any) -> None:
            if not path:
                return
            try:
                p = Path(str(path)).expanduser()
            except Exception:
                return

            # Accepte soit TAGame\\Config directement, soit Rocket League / rocketleague,
            # soit TAGame, et normalise vers TAGame\\Config.
            parts_lower = [part.lower() for part in p.parts]
            if p.name.lower() == "config" and len(p.parts) >= 2 and p.parent.name.lower() == "tagame":
                target = p
            elif p.name.lower() == "tagame":
                target = p / "Config"
            elif p.name.lower() in {"rocket league", "rocketleague"}:
                target = p / "TAGame" / "Config"
            else:
                target = p

            if target not in candidates:
                candidates.append(target)

        home = Path.home()
        userprofile = Path(os.environ.get("USERPROFILE", str(home)))

        document_roots = [
            home / "Documents",
            userprofile / "Documents",
            userprofile / "OneDrive" / "Documents",
        ]

        for env_name in ("OneDrive", "OneDriveConsumer", "OneDriveCommercial"):
            env_value = os.environ.get(env_name)
            if env_value:
                document_roots.append(Path(env_value) / "Documents")

        for docs in document_roots:
            add_candidate(docs / "My Games" / "Rocket League" / "TAGame" / "Config")

        # Recherche limitée dans Documents/OneDrive pour les cas où le dossier est déplacé.
        for docs in document_roots:
            try:
                if not docs.exists():
                    continue
                for found in docs.rglob("Rocket League"):
                    add_candidate(found)
                for found in docs.rglob("rocketleague"):
                    add_candidate(found)
            except Exception:
                pass

        # Bibliothèques Steam officielles.
        steam_roots = [
            Path(os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)")) / "Steam",
            Path(os.environ.get("ProgramFiles", r"C:\Program Files")) / "Steam",
        ]

        def parse_steam_libraryfolders(vdf_path: Path) -> List[Path]:
            libs: List[Path] = []
            try:
                raw = vdf_path.read_text(encoding="utf-8", errors="ignore")
            except Exception:
                return libs
            for match in re.finditer(r'"path"\s*"([^"]+)"', raw):
                value = match.group(1).replace("\\\\", "\\")
                try:
                    libs.append(Path(value))
                except Exception:
                    pass
            return libs

        for steam_root in steam_roots:
            add_candidate(steam_root / "steamapps" / "common" / "rocketleague" / "TAGame" / "Config")
            for lib in parse_steam_libraryfolders(steam_root / "steamapps" / "libraryfolders.vdf"):
                add_candidate(lib / "steamapps" / "common" / "rocketleague" / "TAGame" / "Config")

        # Manifestes Epic : permet de retrouver un chemin Epic déplacé.
        epic_manifest_dirs = [
            Path(os.environ.get("PROGRAMDATA", r"C:\ProgramData")) / "Epic" / "EpicGamesLauncher" / "Data" / "Manifests",
        ]
        for manifest_dir in epic_manifest_dirs:
            try:
                if not manifest_dir.exists():
                    continue
                for manifest in manifest_dir.glob("*.item"):
                    try:
                        data = json.loads(manifest.read_text(encoding="utf-8", errors="ignore"))
                    except Exception:
                        continue
                    searchable = " ".join(str(data.get(k, "")) for k in ("AppName", "DisplayName", "CatalogNamespace", "InstallLocation")).lower()
                    if "rocket" in searchable and ("league" in searchable or "rocketleague" in searchable):
                        add_candidate(Path(str(data.get("InstallLocation", ""))) / "TAGame" / "Config")
            except Exception:
                pass

        # Chemins classiques Steam/Epic en dernier recours.
        classic_paths = [
            Path(r"C:\Program Files\Epic Games\rocketleague\TAGame\\Config"),
            Path(r"C:\Program Files (x86)\Epic Games\rocketleague\TAGame\\Config"),
            Path(r"C:\Program Files (x86)\Steam\steamapps\common\rocketleague\TAGame\\Config"),
            Path(r"C:\Program Files\Steam\steamapps\common\rocketleague\TAGame\\Config"),
        ]
        for path in classic_paths:
            add_candidate(path)

        # Garde uniquement les cibles plausibles.
        unique: List[Path] = []
        seen: Set[str] = set()
        for candidate in candidates:
            try:
                resolved_key = str(candidate.resolve()).lower() if candidate.exists() else str(candidate).lower()
            except Exception:
                resolved_key = str(candidate).lower()
            if resolved_key in seen:
                continue
            seen.add(resolved_key)

            # On accepte si TAGame\\Config existe, ou si TAGame existe et Config peut être créé.
            if candidate.exists() or candidate.parent.exists():
                unique.append(candidate)

        return unique

    def _normalize_rl_config_dir(self, folder: str) -> Optional[Path]:
        if not folder:
            return None
        p = Path(folder)
        if p.name.lower() == "config" and p.parent.name.lower() == "tagame":
            return p
        if p.name.lower() == "tagame":
            return p / "Config"
        if p.name.lower() in {"rocket league", "rocketleague"}:
            return p / "TAGame" / "Config"
        if (p / "TAGame" / "Config").exists():
            return p / "TAGame" / "Config"
        return p

    def _remove_managed_statsapi_config(self) -> None:
        """Nettoyage léger au moment de fermer l'application.

        Beta 6.32 : CONFIG RL ne crée plus de fichiers backup et ne restaure plus
        les anciens backups à la fermeture. Les réglages PacketSendRate/Port restent
        donc en place pour éviter que l'utilisateur doive reconfigurer Rocket League.
        Les anciens DefaultStatsAPI.ini.backup* sont simplement supprimés.
        """
        ini_raw = str(self.config.get("managed_statsapi_ini", "") or "").strip()
        backup_raw = str(self.config.get("managed_statsapi_backup", "") or "").strip()

        target_dirs: List[Path] = []
        for raw in ini_raw.split("|") if ini_raw else []:
            try:
                p = Path(raw.strip())
                if p:
                    target_dirs.append(p.parent)
            except Exception:
                pass
        try:
            if target_dirs:
                self._delete_default_statsapi_backups(target_dirs)
        except Exception:
            pass

        for raw in backup_raw.split("|") if backup_raw else []:
            try:
                p = Path(raw.strip())
                if p.exists() and p.is_file():
                    p.unlink()
                    self._log(f"StatsAPI auto : backup supprimé {p}")
            except Exception:
                pass

        self.config["managed_statsapi_ini"] = ""
        self.config["managed_statsapi_backup"] = ""

    def _statsapi_config_files_for_dir(self, target: Path) -> List[Path]:
        """Retourne les fichiers StatsAPI à écrire dans un dossier TAGame\\Config.

        On écrit toujours DefaultStatsAPI.ini et on écrit aussi TAStatsAPI. Si un
        fichier TAStatsAPI existant est déjà présent avec ou sans extension, on
        l'utilise pour éviter de créer un doublon inutile.
        """
        files: List[Path] = []
        seen: Set[str] = set()

        def add(path: Path) -> None:
            try:
                key = str(path.resolve()).lower() if path.exists() else str(path).lower()
            except Exception:
                key = str(path).lower()
            if key not in seen:
                seen.add(key)
                files.append(path)

        add(target / "DefaultStatsAPI.ini")

        ta_found = False
        try:
            if target.exists():
                for found in target.glob("TAStatsAPI*"):
                    if found.name.lower().startswith("tastatsapi") and (found.is_file() or not found.exists()):
                        add(found)
                        ta_found = True
        except Exception:
            pass

        if not ta_found:
            add(target / "TAStatsAPI.ini")

        return files

    def _find_tastatsapi_files_by_name(self, target_dirs: Optional[List[Path]] = None) -> List[Path]:
        """Recherche un fichier TAStatsAPI* dans les dossiers Rocket League probables."""
        roots: List[Path] = []

        def add_root(path: Any) -> None:
            if not path:
                return
            try:
                p = Path(str(path)).expanduser()
            except Exception:
                return
            if p not in roots:
                roots.append(p)

        for target in target_dirs or []:
            add_root(target)

        home = Path.home()
        userprofile = Path(os.environ.get("USERPROFILE", str(home)))
        for root in (
            home / "Documents" / "My Games" / "Rocket League" / "TAGame" / "Config",
            userprofile / "Documents" / "My Games" / "Rocket League" / "TAGame" / "Config",
            userprofile / "OneDrive" / "Documents" / "My Games" / "Rocket League" / "TAGame" / "Config",
        ):
            add_root(root)

        for env_name in ("OneDrive", "OneDriveConsumer", "OneDriveCommercial"):
            env_value = os.environ.get(env_name)
            if env_value:
                add_root(Path(env_value) / "Documents" / "My Games" / "Rocket League" / "TAGame" / "Config")

        # Ajoute aussi les dossiers détectés par la logique Steam/Epic/Documents existante.
        try:
            for target in self._candidate_rl_config_dirs("all"):
                add_root(target)
        except Exception:
            pass

        files: List[Path] = []
        seen: Set[str] = set()

        def add_file(path: Path) -> None:
            try:
                key = str(path.resolve()).lower() if path.exists() else str(path).lower()
            except Exception:
                key = str(path).lower()
            if key not in seen:
                seen.add(key)
                files.append(path)

        for root in roots:
            try:
                if not root.exists():
                    continue
                for found in root.rglob("TAStatsAPI*"):
                    if found.is_file() and found.name.lower().startswith("tastatsapi"):
                        add_file(found)
            except Exception:
                pass

        return files

    def _preferred_tastatsapi_file_for_help(self, folder: Path) -> Path:
        try:
            found = self._find_tastatsapi_files_by_name([folder])
            if found:
                return found[0]
        except Exception:
            pass
        return folder / "TAStatsAPI.ini"

    def _delete_default_statsapi_backups(self, target_dirs: List[Path]) -> None:
        """Supprime les anciens DefaultStatsAPI.ini.backup* dans les dossiers cibles."""
        seen_dirs: Set[str] = set()
        for target in target_dirs or []:
            try:
                folder = Path(target)
                key = str(folder.resolve()).lower() if folder.exists() else str(folder).lower()
                if key in seen_dirs:
                    continue
                seen_dirs.add(key)
                if not folder.exists():
                    continue
                for old_backup in folder.glob("DefaultStatsAPI.ini.backup*"):
                    try:
                        if old_backup.is_file():
                            old_backup.unlink()
                            self._log(f"StatsAPI auto : ancien backup supprimé {old_backup}")
                    except Exception:
                        pass
            except Exception:
                pass

    def _write_statsapi_ini_to_dirs(self, target_dirs: List[Path], port: int) -> Tuple[List[Path], List[str], List[str]]:
        content = "[TAGame.MatchStatsExporter_TA]\nPacketSendRate=30\n" + f"Port={port}\n"
        written: List[Path] = []
        backups: List[str] = []
        errors: List[str] = []
        files_to_write: List[Path] = []
        seen_files: Set[str] = set()

        def add_file(path: Path) -> None:
            try:
                key = str(path.resolve()).lower() if path.exists() else str(path).lower()
            except Exception:
                key = str(path).lower()
            if key not in seen_files:
                seen_files.add(key)
                files_to_write.append(path)

        for target in target_dirs:
            try:
                target.mkdir(parents=True, exist_ok=True)
            except Exception:
                pass
            for ini_path in self._statsapi_config_files_for_dir(target):
                add_file(ini_path)

        # Recherche par nom : si un TAStatsAPI existe dans un dossier déplacé, on l'écrit aussi.
        for ta_path in self._find_tastatsapi_files_by_name(target_dirs):
            add_file(ta_path)

        for ini_path in files_to_write:
            try:
                ini_path.parent.mkdir(parents=True, exist_ok=True)
                try:
                    if ini_path.name.lower() == "defaultstatsapi.ini":
                        self._delete_default_statsapi_backups([ini_path.parent])
                except Exception:
                    pass

                # Beta 6.32 : ne crée plus de DefaultStatsAPI.ini.backup*.
                # Le bouton CONFIG RL applique directement PacketSendRate/Port.
                backup_path = None
                ini_path.write_text(content, encoding="utf-8")
                written.append(ini_path)
                backups.append("")
                self._log(f"StatsAPI auto : écrit {ini_path}")
            except Exception as exc:
                errors.append(f"{ini_path} : {exc}")
                self._log(f"StatsAPI auto : impossible d'écrire {ini_path} : {exc}")

        return written, backups, errors

    def _install_statsapi_config(self) -> None:
        """Configure automatiquement PacketSendRate + Port pour Rocket League."""
        self._save_api_settings()

        try:
            port = int(self.config.get("statsapi_port", DEFAULT_STATSAPI_PORT))
        except Exception:
            port = DEFAULT_STATSAPI_PORT

        target_dirs = self._candidate_rl_config_dirs("all")

        # Si aucun dossier n'est détecté directement, recherche par nom de fichier TAStatsAPI*.
        if not target_dirs:
            try:
                found_ta_files = self._find_tastatsapi_files_by_name([])
                target_dirs = [p.parent for p in found_ta_files if p.parent.exists()]
            except Exception:
                target_dirs = []

        # Si rien n'est détecté, fallback manuel propre.
        if not target_dirs:
            folder = QFileDialog.getExistingDirectory(
                self,
                "Sélectionne Rocket League, TAGame ou TAGame\\Config",
                str(Path.home()),
            )
            normalized = self._normalize_rl_config_dir(folder)
            if normalized:
                target_dirs = [normalized]

        if not target_dirs:
            QMessageBox.warning(
                self,
                "Configuration Rocket League",
                "Aucun dossier Rocket League TAGame\\Config ni fichier TAStatsAPI n'a été trouvé.\n"
                "Tu peux relancer le bouton puis sélectionner le dossier manuellement."
            )
            return

        self._delete_default_statsapi_backups(target_dirs)
        written, backups, errors = self._write_statsapi_ini_to_dirs(target_dirs, port)

        if written:
            self.config["managed_statsapi_ini"] = "|".join(str(p) for p in written)
            self.config["managed_statsapi_backup"] = ""
            self.config["rl_config_auto_paths"] = "|".join(str(p.parent) for p in written)
            self.config.save()

            if errors:
                self._log("Config RL : certains emplacements n’ont pas pu être écrits : " + " | ".join(errors[:4]))
            self._show_config_success_overlay(port)
        else:
            details = "\n".join(errors[:6]) if errors else "Aucun chemin valide détecté."
            QMessageBox.warning(
                self,
                "Configuration Rocket League impossible",
                "Aucun fichier StatsAPI n'a été écrit.\n\n" + details
            )

    def _save_api_settings(self) -> None:
        self.config["statsapi_host"] = self.host_edit.text().strip() or "127.0.0.1"
        try:
            self.config["statsapi_port"] = int(self.port_edit.text().strip())
        except ValueError:
            self.config["statsapi_port"] = DEFAULT_STATSAPI_PORT
            self.port_edit.setText(str(DEFAULT_STATSAPI_PORT))
        self._log("Paramètres StatsAPI sauvegardés")
        self.stats_client.reconnect()

    def _regenerate_token(self) -> None:
        self.config["remote_key"] = secrets.token_urlsafe(10)
        if hasattr(self, "token_edit"):
            try:
                self.token_edit.setText(self.config["remote_key"])
            except Exception:
                pass
        self._refresh_urls()
        self._publish_state()
        self._log("Token remote régénéré")

