def _crash_report_safe_string(value: Any, limit: int = 4000) -> str:
    try:
        text = str(value)
    except Exception:
        text = repr(value)
    if len(text) > limit:
        text = text[:limit] + "... [truncated]"
    return text

def _crash_report_recent_log_tail(limit: int = 12000) -> str:
    try:
        if CRASH_LOG_PATH.exists():
            raw = CRASH_LOG_PATH.read_text(encoding="utf-8", errors="replace")
            return raw[-limit:]
    except Exception:
        pass
    return ""


def build_crash_report_payload(
    reason: str,
    exc_type: Optional[Any] = None,
    exc: Optional[BaseException] = None,
    tb: Optional[Any] = None,
    *,
    thread_name: str = "main",
    extra: Optional[Dict[str, Any]] = None,
) -> Dict[str, Any]:
    traceback_text = ""
    try:
        if exc_type is not None and exc is not None:
            traceback_text = "".join(traceback.format_exception(exc_type, exc, tb))
    except Exception:
        traceback_text = traceback.format_exc()

    threads: List[Dict[str, Any]] = []
    try:
        for thread in threading.enumerate():
            threads.append({
                "name": _crash_report_safe_string(getattr(thread, "name", "")),
                "ident": _crash_report_safe_string(getattr(thread, "ident", "")),
                "daemon": bool(getattr(thread, "daemon", False)),
                "alive": bool(thread.is_alive()),
            })
    except Exception:
        pass

    payload: Dict[str, Any] = {
        "title": "RL Overlay Studio crash report",
        "reason": _crash_report_safe_string(reason),
        "timestamp_local": time.strftime("%Y-%m-%d %H:%M:%S"),
        "timestamp_utc": time.strftime("%Y-%m-%d %H:%M:%S UTC", time.gmtime()),
        "app": {
            "name": str(globals().get("APP_NAME", "RL Overlay Studio")),
            "version": str(globals().get("APP_VERSION", "")),
            "version_label": str(globals().get("APP_VERSION_LABEL", "")),
            "frozen": bool(getattr(sys, "frozen", False)),
            "executable": _crash_report_safe_string(getattr(sys, "executable", "")),
            "argv": [_crash_report_safe_string(arg, 1000) for arg in getattr(sys, "argv", [])],
            "cwd": _crash_report_safe_string(Path.cwd()),
            "pid": os.getpid(),
        },
        "python": {
            "version": _crash_report_safe_string(sys.version),
            "platform": _crash_report_safe_string(sys.platform),
        },
        "paths": {
            "app_data_dir": _crash_report_safe_string(APP_DATA_DIR),
            "config_path": _crash_report_safe_string(CONFIG_PATH),
            "crash_dir": _crash_report_safe_string(CRASH_DIR),
        },
        "exception": {
            "type": _crash_report_safe_string(getattr(exc_type, "__name__", exc_type) if exc_type is not None else ""),
            "message": _crash_report_safe_string(exc or ""),
            "thread": _crash_report_safe_string(thread_name),
            "traceback": traceback_text,
        },
        "threads": threads,
        "recent_crash_log_tail": _crash_report_recent_log_tail(),
    }
    if extra:
        try:
            payload["extra"] = json.loads(json.dumps(extra, default=str))
        except Exception:
            payload["extra"] = {"raw": _crash_report_safe_string(extra)}
    return payload


def write_crash_report(
    reason: str,
    exc_type: Optional[Any] = None,
    exc: Optional[BaseException] = None,
    tb: Optional[Any] = None,
    *,
    thread_name: str = "main",
    extra: Optional[Dict[str, Any]] = None,
) -> Optional[Path]:
    """Crée un rapport CRASH détaillé dans %APPDATA%/RL Overlay Studio/AppData/Crash."""
    try:
        CRASH_DIR.mkdir(parents=True, exist_ok=True)
        safe_reason = re.sub(r"[^a-zA-Z0-9_-]+", "_", str(reason or "crash")).strip("_")[:48] or "crash"
        stamp = time.strftime("%Y%m%d_%H%M%S")
        pid = os.getpid()
        json_path = CRASH_DIR / f"CRASH_{stamp}_{pid}_{safe_reason}.json"
        txt_path = CRASH_DIR / f"CRASH_{stamp}_{pid}_{safe_reason}.txt"

        payload = build_crash_report_payload(reason, exc_type, exc, tb, thread_name=thread_name, extra=extra)

        json_text = json.dumps(payload, indent=2, ensure_ascii=False, default=str)
        json_path.write_text(json_text, encoding="utf-8")
        CRASH_LAST_JSON_PATH.write_text(json_text, encoding="utf-8")

        txt_lines = [
            "RL Overlay Studio - CRASH REPORT",
            "=" * 42,
            f"Date locale : {payload.get('timestamp_local', '')}",
            f"Version : {payload.get('app', {}).get('version_label') or payload.get('app', {}).get('version')}",
            f"Raison : {payload.get('reason', '')}",
            f"Thread : {payload.get('exception', {}).get('thread', '')}",
            f"Exception : {payload.get('exception', {}).get('type', '')} - {payload.get('exception', {}).get('message', '')}",
            "",
            "Traceback :",
            payload.get("exception", {}).get("traceback", "") or "(pas de traceback Python disponible)",
            "",
            "Chemins :",
            f"- AppData : {payload.get('paths', {}).get('app_data_dir', '')}",
            f"- Config : {payload.get('paths', {}).get('config_path', '')}",
            f"- Crash : {payload.get('paths', {}).get('crash_dir', '')}",
            "",
            "Threads actifs :",
        ]
        for thread in payload.get("threads", []):
            txt_lines.append(f"- {thread.get('name')} | daemon={thread.get('daemon')} | alive={thread.get('alive')}")
        txt_text = "\n".join(txt_lines)
        txt_path.write_text(txt_text, encoding="utf-8")
        CRASH_LAST_TXT_PATH.write_text(txt_text, encoding="utf-8")

        try:
            with CRASH_LOG_PATH.open("a", encoding="utf-8") as f:
                f.write(f"\n[{payload.get('timestamp_local')}] {reason} -> {json_path.name}\n")
        except Exception:
            pass
        try:
            append_recent_error_log("CRASH_REPORT", txt_text, {"json_report": str(json_path), "txt_report": str(txt_path)})
        except Exception:
            pass
        return json_path
    except Exception:
        return None


def install_crash_report_hooks() -> None:
    """Installe les hooks crash Python + threads + faulthandler natif."""
    previous_excepthook = getattr(sys, "excepthook", None)

    def _safe_excepthook(exc_type: Any, exc: BaseException, tb: Any) -> None:
        write_crash_report("unhandled_exception", exc_type, exc, tb, thread_name="main")
        try:
            if previous_excepthook and previous_excepthook is not _safe_excepthook:
                previous_excepthook(exc_type, exc, tb)
        except Exception:
            pass

    def _safe_threading_excepthook(args: Any) -> None:
        thread_obj = getattr(args, "thread", None)
        thread_name = str(getattr(thread_obj, "name", "") or "thread")
        write_crash_report(
            "thread_exception",
            getattr(args, "exc_type", None),
            getattr(args, "exc_value", None),
            getattr(args, "exc_traceback", None),
            thread_name=thread_name,
        )

    sys.excepthook = _safe_excepthook
    try:
        threading.excepthook = _safe_threading_excepthook
    except Exception:
        pass

    # Captures crashs natifs/Qt/PyInstaller quand Python peut encore écrire.
    # Le fichier peut exister avant crash, mais il ne contient une pile utile que si
    # un crash fatal arrive.
    try:
        CRASH_DIR.mkdir(parents=True, exist_ok=True)
        fatal_file = open(CRASH_FATAL_LOG_PATH, "a", encoding="utf-8")
        fatal_file.write(f"\n\n[{time.strftime('%Y-%m-%d %H:%M:%S')}] Crash native monitor started · {globals().get('APP_VERSION', '')}\n")
        fatal_file.flush()
        faulthandler.enable(file=fatal_file, all_threads=True)
        globals()["_RLOS_FATAL_CRASH_FILE_HANDLE"] = fatal_file
    except Exception:
        pass




def _windows_startup_folder() -> Optional[Path]:
    if not sys.platform.lower().startswith("win"):
        return None
    appdata = os.environ.get("APPDATA", "")
    if not appdata:
        return None
    return Path(appdata) / "Microsoft" / "Windows" / "Start Menu" / "Programs" / "Startup"


def _autostart_watcher_vbs_path() -> Optional[Path]:
    folder = _windows_startup_folder()
    if folder is None:
        return None
    return folder / "RL Overlay Studio Rocket League Watcher.vbs"


def _autostart_main_vbs_path() -> Optional[Path]:
    folder = _windows_startup_folder()
    if folder is None:
        return None
    return folder / "RL Overlay Studio.vbs"


def _windows_run_key_path() -> str:
    return r"Software\Microsoft\Windows\CurrentVersion\Run"


def _app_start_command(extra_args: Optional[List[str]] = None) -> str:
    args = list(extra_args or [])
    if getattr(sys, "frozen", False):
        cmd = [str(Path(sys.executable).resolve())] + args
    else:
        cmd = [str(Path(sys.executable).resolve()), str(Path(__file__).resolve())] + args
    try:
        return subprocess.list2cmdline(cmd)
    except Exception:
        return " ".join(f'"{x}"' if " " in str(x) else str(x) for x in cmd)


def _vbs_string_literal(value: str) -> str:
    """Retourne une chaîne VBScript valide.

    VBScript n'utilise pas \\" pour échapper les guillemets : il faut les doubler.
    L'ancien writer générait donc des fichiers .vbs invalides avec les chemins entre
    guillemets, ce qui affichait Windows Script Host au démarrage.
    """
    return '"' + str(value or "").replace('"', '""') + '"'


def _write_hidden_vbs(path: Path, command: str) -> bool:
    try:
        path.parent.mkdir(parents=True, exist_ok=True)
        content = (
            'Option Explicit\\r\\n'
            'Dim WshShell\\r\\n'
            'Set WshShell = CreateObject("WScript.Shell")\\r\\n'
            'WshShell.Run ' + _vbs_string_literal(command) + ', 0, False\\r\\n'
        )
        if path.exists() and path.read_text(encoding="utf-8", errors="ignore") == content:
            return True
        path.write_text(content, encoding="utf-8")
        return True
    except Exception:
        return False


def cleanup_legacy_autostart_vbs_files() -> bool:
    """Supprime les anciens VBS Startup qui peuvent afficher Windows Script Host.

    Depuis Beta 7.61, le démarrage stable passe par HKCU Run + tâche planifiée.
    Les VBS ne sont plus nécessaires et peuvent provoquer des pop-ups s'ils ont été
    générés avec une syntaxe incorrecte dans une version précédente.
    """
    ok = True
    for p in (_autostart_main_vbs_path(), _autostart_watcher_vbs_path()):
        if p is None:
            continue
        try:
            if p.exists():
                p.unlink()
        except Exception:
            ok = False
    return ok

def _safe_unlink(path: Optional[Path]) -> bool:
    if path is None:
        return False
    try:
        if path.exists():
            path.unlink()
        return True
    except Exception:
        return False


def _set_windows_run_value(name: str, command: str) -> bool:
    if not sys.platform.lower().startswith("win"):
        return False
    try:
        import winreg  # type: ignore
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, _windows_run_key_path(), 0, winreg.KEY_SET_VALUE) as key:
            winreg.SetValueEx(key, name, 0, winreg.REG_SZ, command)
        return True
    except Exception:
        return False


def _delete_windows_run_value(name: str) -> bool:
    if not sys.platform.lower().startswith("win"):
        return False
    try:
        import winreg  # type: ignore
        with winreg.OpenKey(winreg.HKEY_CURRENT_USER, _windows_run_key_path(), 0, winreg.KEY_SET_VALUE) as key:
            try:
                winreg.DeleteValue(key, name)
            except FileNotFoundError:
                pass
        return True
    except Exception:
        return False



def _set_windows_scheduled_task(task_name: str, command: str, enabled: bool = True) -> bool:
    """Crée/supprime une tâche planifiée utilisateur ONLOGON.

    Fallback plus robuste que Startup/VBS sur certains Windows où les scripts VBS
    ou le dossier Startup sont bloqués. La tâche est LIMITED : pas besoin admin.
    """
    if not sys.platform.lower().startswith("win"):
        return False
    try:
        schtasks = shutil.which("schtasks.exe") or "schtasks.exe"
        creationflags = getattr(subprocess, "CREATE_NO_WINDOW", 0)
        startupinfo = None
        try:
            startupinfo = subprocess.STARTUPINFO()
            startupinfo.dwFlags |= subprocess.STARTF_USESHOWWINDOW
            startupinfo.wShowWindow = 0
        except Exception:
            startupinfo = None
        if enabled:
            args = [
                schtasks,
                "/Create",
                "/TN", task_name,
                "/SC", "ONLOGON",
                "/TR", command,
                "/RL", "LIMITED",
                "/F",
            ]
        else:
            args = [schtasks, "/Delete", "/TN", task_name, "/F"]
        result = subprocess.run(
            args,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            stdin=subprocess.DEVNULL,
            timeout=8,
            creationflags=creationflags,
            startupinfo=startupinfo,
        )
        return result.returncode == 0
    except Exception:
        return False

def install_windows_startup_launch(enabled: bool = True) -> bool:
    """Lance l'application au démarrage Windows via HKCU Run.

    Le registre HKCU est plus stable que le fichier VBS seul dans le dossier Startup :
    il ne dépend pas de l'affichage des extensions/fichiers du dossier démarrage et
    survit mieux aux mises à jour de l'application.
    """
    if not sys.platform.lower().startswith("win"):
        return False
    command = _app_start_command(["--windows-startup"])
    run_ok = _set_windows_run_value("RL Overlay Studio", command) if enabled else _delete_windows_run_value("RL Overlay Studio")
    task_ok = _set_windows_scheduled_task("RL Overlay Studio", command, enabled=enabled)

    # Beta 7.61 : plus de fallback VBS dans Startup.
    # Les VBS peuvent afficher des erreurs Windows Script Host si le chemin est mal
    # échappé ou si Windows bloque WSH. On nettoie les anciens fichiers et on garde
    # les méthodes stables : HKCU Run + tâche planifiée.
    cleanup_legacy_autostart_vbs_files()
    return bool(run_ok or task_ok)


def cleanup_legacy_rocket_league_autostart_watcher() -> bool:
    """Supprime les anciennes entrées qui lançaient l'app quand Rocket League s'ouvrait."""
    if not sys.platform.lower().startswith("win"):
        return False
    ok = True
    try:
        ok = _delete_windows_run_value("RL Overlay Studio Rocket League Watcher") and ok
    except Exception:
        ok = False
    try:
        # Supprime l'ancienne tâche planifiée ONLOGON si elle existe.
        ok = _set_windows_scheduled_task("RL Overlay Studio Rocket League Watcher", "", enabled=False) and ok
    except Exception:
        ok = False
    try:
        p = _autostart_watcher_vbs_path()
        if p is not None and p.exists():
            p.unlink()
    except Exception:
        ok = False
    return ok


def install_stable_autostart_system(windows_startup: bool = True) -> Dict[str, bool]:
    """Installe/retire uniquement le lancement au démarrage du PC."""
    watcher_removed = cleanup_legacy_rocket_league_autostart_watcher()
    return {
        "windows_startup": install_windows_startup_launch(bool(windows_startup)),
        "rocket_league_watcher_removed": watcher_removed,
    }


def main() -> None:
    # Beta 7.61 : le mode watcher Rocket League est retiré.
    # Si une ancienne tâche appelle encore --watch-rocket-league, on quitte sans relancer de boucle.
    if "--watch-rocket-league" in sys.argv:
        return
    install_crash_report_hooks()

    app: Optional[QApplication] = None
    try:
        startup_to_tray = "--windows-startup" in sys.argv
        if not acquire_single_instance_lock():
            if notify_existing_instance_show_window():
                return
            if "--auto-start-from-rl" not in sys.argv and "--windows-startup" not in sys.argv:
                show_already_running_message()
            return

        app = QApplication(sys.argv)
        # Beta 7.61 : l'application peut vivre en zone de notification au démarrage Windows.
        # La fermeture de la fenêtre principale appelle shutdown_application(), donc elle
        # quitte toujours totalement l'application malgré QuitOnLastWindowClosed(False).
        app.setQuitOnLastWindowClosed(False)

        loaded_fonts = load_local_design_fonts()
        asset_warnings = verify_design_assets_lock()
        protection_warnings = verify_app_protection_lock()

        icon_path = APP_ICON_PNG if APP_ICON_PNG.exists() else APP_ICON_ICO
        if icon_path.exists():
            app.setWindowIcon(QIcon(str(icon_path)))
        app.setStyle("Fusion")
        app.setStyleSheet(APP_STYLE)
        font = QFont(DESIGN_FONT_FAMILY, 10)
        try:
            font.setFallbackFamilies(DESIGN_FONT_FALLBACKS)
        except Exception:
            pass
        app.setFont(font)
        win = RLOverlayStudio(start_hidden_to_tray=startup_to_tray)
        if loaded_fonts:
            win._log("Polices locales chargées · " + ", ".join(sorted(set(loaded_fonts))))
        if asset_warnings:
            win._log("Attention assets design · " + " | ".join(asset_warnings[:8]))
        if protection_warnings:
            win._log("Protection fichiers · " + " | ".join(protection_warnings[:8]))
        else:
            win._log("Protection fichiers importants · intégrité OK")
        if startup_to_tray and getattr(win, "_tray_icon", None) is not None:
            try:
                win._tray_icon.show()
                win._tray_icon.showMessage(
                    "RL Overlay Studio",
                    win._translate_text_value("Application active en zone de notification."),
                    QSystemTrayIcon.MessageIcon.Information,
                    3500,
                )
            except Exception:
                pass
            win.hide()
        else:
            # Fallback de sécurité : si la zone de notification est indisponible,
            # on affiche la fenêtre afin que l'utilisateur ne perde pas l'accès à l'app.
            win.show()
        sys.exit(app.exec())
    except SystemExit:
        raise
    except Exception as exc:
        write_crash_report("main_exception", type(exc), exc, exc.__traceback__, thread_name="main")
        raise


if __name__ == "__main__":
    main()